package org.humanjourney.core.advancement;
import java.util.*;
import java.nio.file.*;
import java.io.*;
import java.util.concurrent.*;
import com.google.gson.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.packs.resources.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.network.RegistryFriendlyByteBuf;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import org.mockito.MockedStatic;
class NativeTransportTest {
 static MockedStatic<net.minecraftforge.fml.ModLoader> loader;
 @BeforeAll static void bootstrap(){loader=mockStatic(net.minecraftforge.fml.ModLoader.class);loader.when(net.minecraftforge.fml.ModLoader::get).thenReturn(mock(net.minecraftforge.fml.ModLoader.class));net.minecraft.SharedConstants.tryDetectVersion();net.minecraft.server.Bootstrap.bootStrap();}
 @AfterAll static void close(){loader.close();}
 @AfterEach void clear(){NativeStore.reset();}
 void reload(String data,boolean references)throws Exception{var manager=mock(ResourceManager.class);when(manager.getResource(any())).thenAnswer(q->{var key=(ResourceLocation)q.getArgument(0);if(key.toString().equals(NativeReloadListener.PATH)){if(data==null)return Optional.empty();var r=mock(Resource.class);when(r.sourcePackId()).thenReturn("synthetic");when(r.openAsReader()).thenAnswer(a->new BufferedReader(new StringReader(data)));return Optional.of(r);}return references?Optional.of(mock(Resource.class)):Optional.empty();});var barrier=new PreparableReloadListener.PreparationBarrier(){public <T> CompletableFuture<T> wait(T x){return CompletableFuture.completedFuture(x);}};new NativeReloadListener().reload(barrier,manager,Runnable::run,Runnable::run).join();}
 @Test void actualReloadAcceptsThenInvalidFallsBackAtomicallyToVanilla()throws Exception{reload(NativePresentationTest.example().toString(),true);assertEquals(1,NativeStore.state().model().tabs().size());reload("{}",true);assertTrue(NativeStore.state().model().tabs().isEmpty());assertFalse(NativeStore.state().error().isEmpty());reload(null,true);assertTrue(NativeStore.state().error().isEmpty());assertEquals("missing",NativeStore.state().source());}
 @Test void missingNativeResourceIsClearlyDiagnosed()throws Exception{reload(NativePresentationTest.example().toString(),false);assertTrue(NativeStore.state().error().contains("unknown advancement reference"));assertTrue(NativeStore.state().model().tabs().isEmpty());}
 @Test void oversizedResourceIsRejected()throws Exception{reload(" ".repeat(NativePresentation.MAX_JSON+1),true);assertTrue(NativeStore.state().error().contains("512KiB"));}
 NativePackets.Frame wire(NativePackets.Frame p){var b=new RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),RegistryAccess.fromRegistryOfRegistries(BuiltInRegistries.REGISTRY));try{NativePackets.CODEC.encode(b,p);assertTrue(b.readableBytes()<=24*1024);return NativePackets.CODEC.decode(b);}finally{b.release();}}
 @Test void nativeCodecMirrorRoundTripAndClear()throws Exception{var model=NativePresentationTest.parse(NativePresentationTest.example());var mirror=new NativeMirror();var session=UUID.randomUUID();for(var p:NativePackets.frames(session,1,model))assertTrue(mirror.accept(wire(p)));assertEquals(model,mirror.view());NativePackets.frames(session,2,NativePresentation.empty()).forEach(mirror::accept);NativePackets.frames(session,1,model).forEach(mirror::accept);assertTrue(mirror.view().tabs().isEmpty());}
 @Test void largeBoundedSnapshotReconstructsAtomicallyInReverseOrder()throws Exception{var o=NativePresentationTest.example();var t=o.getAsJsonArray("tabs").get(0).getAsJsonObject();var positions=new JsonArray();for(int i=0;i<511;i++){var p=new JsonObject();p.addProperty("advancement","human_journey:test/n"+i);p.addProperty("x",i*10);p.addProperty("y",0);positions.add(p);}t.add("positions",positions);t.add("connections",new JsonArray());t.add("eras",new JsonArray());var model=NativePresentation.parse(o,id->true);var frames=NativePackets.frames(UUID.randomUUID(),1,model);assertTrue(frames.size()>1);var mirror=new NativeMirror();for(int i=frames.size()-1;i>=0;i--){mirror.accept(wire(frames.get(i)));if(i>0)assertTrue(mirror.view().tabs().isEmpty());}assertEquals(model,mirror.view());}
 @Test void conflictingFragmentsRetainPreviousCompleteView()throws Exception{var model=NativePresentationTest.parse(NativePresentationTest.example());var mirror=new NativeMirror();var session=UUID.randomUUID();NativePackets.frames(session,1,model).forEach(mirror::accept);var p=NativePackets.frames(session,2,model).getFirst();var bad=p.data();bad[0]^=1;mirror.accept(new NativePackets.Frame(p.session(),p.sequence(),p.part(),p.parts(),p.length(),bad,false));assertEquals(model,mirror.view());}
 @Test void pureValidationRejectsQuotaOverflowAndSelfLinks()throws Exception{var o=NativePresentationTest.example();var p=o.getAsJsonArray("tabs").get(0).getAsJsonObject().getAsJsonArray("positions");for(int i=0;i<512;i++){var a=new JsonObject();a.addProperty("advancement","human_journey:test/n"+i);a.addProperty("x",i);a.addProperty("y",0);p.add(a);}assertThrows(IllegalArgumentException.class,()->NativePresentationTest.parse(o));}
 @Test void nativeCodeHasNoStateWritesAndClientClassesStayIsolated()throws Exception{var root=NativePresentationTest.project().resolve("src/main/java/org/humanjourney/core/advancement");for(String name:List.of("NativeServer.java","mixin/PlayerAdvancementsMixin.java")){String s=Files.readString(root.resolve(name));for(String forbidden:List.of(".award(",".revoke(","getOrStartProgress(","setScore(","getOrCreatePlayerScore("))assertFalse(s.contains(forbidden),forbidden);}for(String name:List.of("NativeServer","NativeBootstrap","NativePresentation","NativePackets","NativeMirror"))try(var in=getClass().getResourceAsStream("/org/humanjourney/core/advancement/"+name+".class")){assertNotNull(in);assertFalse(new String(in.readAllBytes(),java.nio.charset.StandardCharsets.ISO_8859_1).contains("net/minecraft/client/"));}}
 @Test void exactNativeUiHooksDoNotReplaceVanillaRenderingOrInput()throws Exception{var root=NativePresentationTest.project();String tab=Files.readString(root.resolve("src/main/java/org/humanjourney/core/advancement/mixin/AdvancementTabMixin.java"));assertTrue(tab.contains("ordinal=0"));assertTrue(tab.contains("drawConnectivity(Lnet/minecraft/client/gui/GuiGraphics;IIZ)V"));assertFalse(tab.contains("cancellable=true"));assertFalse(tab.contains("@Overwrite"));String widget=Files.readString(root.resolve("src/main/java/org/humanjourney/core/advancement/mixin/AdvancementWidgetMixin.java"));assertFalse(widget.contains("@Inject"));assertFalse(widget.contains("setLocation"));var clazz=new org.objectweb.asm.tree.ClassNode();try(var in=getClass().getResourceAsStream("/net/minecraft/client/gui/screens/advancements/AdvancementTab.class")){new org.objectweb.asm.ClassReader(in).accept(clazz,0);}var method=clazz.methods.stream().filter(m->m.name.equals("drawContents")).findFirst().orElseThrow();assertEquals(2,java.util.stream.StreamSupport.stream(method.instructions.spliterator(),false).filter(i->i instanceof org.objectweb.asm.tree.MethodInsnNode m&&m.name.equals("drawConnectivity")).count());}
}
